  static AiModelProfile? lookup(String id) {
    final normalized = id.replaceFirst('qwen3-8-', 'qwen3.8-');
    if (normalized == 'qwen3.8-omni-flash-realtime') return _realtime;
    if (normalized.endsWith('-fp8') || normalized == 'qwen3.8-flash-next') {
      return openWeights(normalized);
    }
    const names = {
      'qwen3.8-max': 'Qwen3.8-Max',
      'qwen3.8-max-0902': 'Qwen3.8-Max 2026-09-02',
      'qwen3.8-max-2026-09-02': 'Qwen3.8-Max 2026-09-02',
      'qwen3.8-flash': 'Qwen3.8-Flash',
      'qwen3.8-27b': 'Qwen3.8-27B',
      'qwen3.8-2.4t-a95b': 'Qwen3.8-2.4T-A95B',
      'qwen3.8-omni-flash': 'Qwen3.8-Omni-Flash',
    };
    final name = names[normalized];
    if (name == null) return null;
    return _cache.putIfAbsent(normalized, () {
      final moe = normalized == 'qwen3.8-2.4t-a95b';
      final dense = normalized == 'qwen3.8-27b';
      final omni = normalized == 'qwen3.8-omni-flash';
      final flash = normalized == 'qwen3.8-flash';
      final max = normalized.startsWith('qwen3.8-max');
      final snapshot = max && normalized != 'qwen3.8-max';
      final preserve = max || flash || omni;
      final modalities = moe
          ? _text
          : omni
          ? _omni
          : _vision;
      final source =
          'https://help.aliyun.com/${omni ? 'zh' : 'en'}/model-studio/'
          '${max ? 'qwen3-8-max' : normalized.replaceAll('.', '-')}';
      final pricing = <String, Object?>{
        if (max || moe) ...{
          'beijing': {
            ..._maxPrice,
            if (max && !snapshot) ...{
              'batch_file_input': 6,
              'batch_file_output': 18,
              'batch_chat_input': 12,
              'batch_chat_output': 36,
            },
          },
          'singapore': _maxSingaporePrice,
          if (max)
            for (final region in ['frankfurt', 'virginia', 'tokyo'])
              region: _maxPrice,
        },
        if (flash) ...{
          'beijing': _flashPrice,
          'singapore': {
            'input': 1.094,
            'output': 3.427,
            'implicit_cache_read': 0.117,
            'explicit_cache_write': 1.458,
            'explicit_cache_read': 0.117,
          },
          for (final region in ['frankfurt', 'virginia', 'tokyo'])
            region: _flashPrice,
        },
        if (omni) ...{
          for (final region in ['beijing', ..._globalRegions])
            region: {'input': 0.8, 'output': 2.7, 'implicit_cache_read': 0.1},
          'singapore': {
            'input': 1.094,
            'output': 3.427,
            'implicit_cache_read': 0.117,
          },
        },
        if (dense) ...{
          'beijing': {
            'input': 3,
            'output': 12,
            'implicit_cache_read': 0.6,
            'explicit_cache_write': 3.75,
            'explicit_cache_read': 0.3,
          },
          'singapore': {
            'input': 3.646,
            'output': 21.875,
            'implicit_cache_read': 0.729,
            'explicit_cache_write': 4.557,
            'explicit_cache_read': 0.365,
          },
        },
      };
      return AiModelProfile(
        displayName: name,
        description: moe
            ? '百炼托管的开源纯文本模型，2.4T 总参数、95B 激活参数，思考常开。'
            : omni
            ? '支持文本、图片、音频、视频理解，仅输出文本；支持多通道音频与工具调用。'
            : '百炼多模态推理模型，支持文本、图片、视频输入、工具调用与结构化输出。',
        canonicalSlug: snapshot ? 'qwen3.8-max-2026-09-02' : normalized,
        huggingFaceId: _weightsNames[normalized] == null
