          if (!omni) 'repetition_penalty': 1.0,
          'seed': 1234,
          'stream': false,
          'parallel_tool_calls': false,
          'enable_search': false,
          'response_format': {'type': 'text'},
          if (preserve) 'preserve_thinking': true,
          if (max || flash) 'tool_stream': false,
        },
        links: AiModelLinksMetadata(details: source),
        sourceMetadata: {
          'verified_at': _verifiedAt,
          'deployment': '阿里云百炼',
          'request_policy': 'qwen38_dashscope',
          'api_source': _apiSource,
          'thinking_source':
              'https://help.aliyun.com/zh/model-studio/deep-thinking',
          'input_modalities': modalities.map((value) => value.name).toList(),
          'output_modalities': ['text'],
          'max_input_tokens': {'thinking': 983616, 'non_thinking': 991808},
          'reasoning': {
            'mandatory': moe,
            'default_enabled': true,
            'supported_efforts': _efforts,
            'default_effort': 'xhigh',
            'effort_aliases': {
              'minimal': 'low',
              'high': 'xhigh',
              'max': 'xhigh',
            },
            'none': moe ? '不支持关闭思考' : '关闭思考',
          },
          'mutually_exclusive_parameters': [
