            'active_parameters': 95000000000,
          },
          if (dense) 'total_parameters': 27000000000,
          'regions': [
            'beijing',
            'singapore',
            if (max || flash || omni) ..._globalRegions,
          ],
          'pricing_currency': 'CNY',
          'pricing_unit': '每百万词元',
          'pricing_source': omni
