  static AiModelProfile? openWeights(String id) {
    final normalized = id.startsWith('qwen/') ? id.substring(5) : id;
    final fp8 = normalized.endsWith('-fp8');
    final base = fp8
        ? normalized.substring(0, normalized.length - 4)
        : normalized;
    final name = _weightsNames[base];
    if (name == null) return null;
    return _weightsCache.putIfAbsent(normalized, () {
      final moe = base == 'qwen3.8-2.4t-a95b';
      final fullName = '$name${fp8 ? '-FP8' : ''}';
      final modalities = moe ? _text : _vision;
      return AiModelProfile(
        displayName: fullName,
        description: '开源权重原生支持 262144 上下文；扩展窗口需要服务端配置，不沿用百炼输出或价格限制。',
        canonicalSlug: 'Qwen/$fullName',
        huggingFaceId: 'Qwen/$fullName',
        isMultimodal: !moe,
        supportsAttachments: !moe,
        supportedModalities: modalities,
        architecture: AiModelArchitectureMetadata(
          inputModalities: modalities.map((value) => value.name).toList(),
          outputModalities: const ['text'],
        ),
        maxContextLength: 262144,
        thinkingEnabled: true,
        requiresReasoningEcho: true,
        reasoningEffortControlEnabled: true,
        reasoningEffort: 'xhigh',
        reasoningEffortOptions: AiReasoningEffortOption.standardValues(
          _efforts,
        ),
        supportedParameters: const [
          'model',
          'messages',
          'max_tokens',
          'stream',
          'temperature',
          'top_p',
          'top_k',
          'min_p',
          'presence_penalty',
          'repetition_penalty',
          'tools',
          'reasoning_effort',
          'chat_template_kwargs',
        ],
        defaultParameters: const {
          'reasoning_effort': 'xhigh',
          'chat_template_kwargs': {
            'enable_thinking': true,
            'preserve_thinking': true,
          },
        },
        links: AiModelLinksMetadata(
          details: 'https://huggingface.co/Qwen/$fullName',
        ),
        sourceMetadata: {
          'verified_at': _verifiedAt,
          'deployment': '开源权重；限制由本地推理服务决定',
          'request_policy': 'qwen38_chat_template',
          'reasoning': {'mandatory': moe, 'default_enabled': true},
          'native_context_window': 262144,
          'extended_context_window': moe ? 1010000 : 1000000,
          'recommended_sampling': {
            'thinking': {
              'temperature': 1.0,
              'top_p': 0.95,
              'top_k': 20,
              'min_p': 0.0,
              'presence_penalty': 0.0,
              'repetition_penalty': 1.0,
            },
            if (!moe)
              'non_thinking': {
                'temperature': 0.7,
                'top_p': 0.8,
                'top_k': 20,
                'min_p': 0.0,
                'presence_penalty': 1.5,
                'repetition_penalty': 1.0,
              },
          },
          'license': base == 'qwen3.8-27b'
              ? 'apache-2.0'
              : moe
              ? 'qwen3.8-max'
              : 'qwen-community-1.0',
          'license_source':
              'https://huggingface.co/Qwen/$fullName/blob/main/LICENSE',
          if (base == 'qwen3.8-flash-next') ...{
            'language_model_parameters': 125000000000,
            'active_parameters': 6000000000,
            'additional_ngram_embedding_parameters': 51000000000,
            'additional_mtp_parameters': 4000000000,
          },
          if (moe) ...{
            'total_parameters': 2400000000000,
            'active_parameters': 95000000000,
          },
          if (base == 'qwen3.8-27b') 'total_parameters': 27000000000,
          'weight_precision': fp8 ? 'FP8' : 'BF16',
          'config_source':
              'https://huggingface.co/Qwen/$fullName/blob/main/config.json',
          'config': _weightConfigs.putIfAbsent(
            normalized,
            () => {
              ...jsonDecode(_weightConfigJson[base]!) as Map<String, dynamic>,
              if (fp8)
                'quantization_config': jsonDecode(
                  _weightConfigJson[normalized]!,
                ),
            },
          ),
          'model_card_source':
              'https://huggingface.co/Qwen/$fullName/blob/main/README.md',
        },
      );
    });
  }

